package org.apache.commons.compress.utils;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.Closeable;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.nio.ByteOrder;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class BitInputStream_readBits_TriageGen2Test {

    private static final int MAXIMUM_CACHE_SIZE = 64; // Assuming based on context

    @Test(expected = IllegalArgumentException.class)
    public void testReadBits_NegativeCount() throws IOException {
        BitInputStream bis = new BitInputStream(new ByteArrayInputStream(new byte[]{0}), ByteOrder.BIG_ENDIAN);
        bis.readBits(-1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testReadBits_TooLargeCount() throws IOException {
        // Using a value larger than typical cache size to trigger exception
        BitInputStream bis = new BitInputStream(new ByteArrayInputStream(new byte[]{0}), ByteOrder.BIG_ENDIAN);
        bis.readBits(100); 
    }

    @Test
    public void testReadBits_LittleEndian_SingleByte() throws IOException {
        byte[] data = {(byte) 0xAA}; // 10101010
        BitInputStream bis = new BitInputStream(new ByteArrayInputStream(data), ByteOrder.LITTLE_ENDIAN);

        // Read 4 bits: 0x0A (from the lower bits of 0xAA)
        // In Little Endian: bitsCached |= (nextByte << bitsCachedSize)
        // 0xAA is 1010 1010. First 4 bits are 1010 (0xA)
        assertEquals(0x0AL, bis.readBits(4));
        // Remaining 4 bits: 1010 (0xA)
        assertEquals(0x0AL, bis.readBits(4));
    }

    @Test
    public void testReadBits_LittleEndian_MultiByte() throws IOException {
        byte[] data = {(byte) 0x01, (byte) 0x02}; 
        // LE: bitsCached = 0x0201
        BitInputStream bis = new BitInputStream(new ByteArrayInputStream(data), ByteOrder.LITTLE_ENDIAN);

        // Read 12 bits: 0x201
        assertEquals(0x201L, bis.readBits(12));
    }

    @Test
    public void testReadBits_BigEndian_SingleByte() throws IOException {
        byte[] data = {(byte) 0xAB}; // 1010 1011
        BitInputStream bis = new BitInputStream(new ByteArrayInputStream(data), ByteOrder.BIG_ENDIAN);

        // Read 4 bits: 0xA
        assertEquals(0xAL, bis.readBits(4));
        // Read 4 bits: 0xB
        assertEquals(0xBL, bis.readBits(4));
    }

    @Test
    public void testReadBits_BigEndian_MultiByte() throws IOException {
        byte[] data = {(byte) 0x12, (byte) 0x34};
        BitInputStream bis = new BitInputStream(new ByteArrayInputStream(data), ByteOrder.BIG_ENDIAN);

        // BE: bitsCached = 0x1234
        // bitsCachedSize = 16. Read 12 bits: (0x1234 >> (16 - 12)) & mask = 0x123
        assertEquals(0x123L, bis.readBits(12));
        // Remaining 4 bits: 4
        assertEquals(0x4L, bis.readBits(4));
    }

    @Test
    public void testReadBits_EOF() throws IOException {
        byte[] data = {(byte) 0xFF};
        BitInputStream bis = new BitInputStream(new ByteArrayInputStream(data), ByteOrder.BIG_ENDIAN);

        // Read all 8 bits
        assertEquals(0xFFL, bis.readBits(8));
        // Next read should hit nextByte < 0
        assertEquals(-1L, bis.readBits(1));
    }

    @Test
    public void testReadBits_LargeCount_LE() throws IOException {
        // Test the scenario where bitsCachedSize grows
        byte[] data = {0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x01};
        BitInputStream bis = new BitInputStream(new ByteArrayInputStream(data), ByteOrder.LITTLE_ENDIAN);

        // Reading a large number of bits to ensure logic handles cache growth
        long result = bis.readBits(32);
        assertEquals(1L, result);
    }

    @Test
    public void testClearBitCache() throws IOException {
        byte[] data = {(byte) 0xFF, (byte) 0xFF};
        BitInputStream bis = new BitInputStream(new ByteArrayInputStream(data), ByteOrder.BIG_ENDIAN);

        bis.readBits(4); // Consumes some bits, bitsCachedSize becomes 4
        bis.clearBitCache();

        // After clear, the next read should behave as if we are starting from the first byte
        // but since the InputStream is already advanced, it depends on how clearBitCache is implemented.
        // Assuming it resets bitsCachedSize and bitsCached.
        // This test ensures no crash and verifies internal state reset if visible.
        // Since we can't see internal state, we test functional consistency.
        // If clearBitCache resets bitsCachedSize to 0, the next read will pull from the stream.
        // We'll just call it to ensure coverage.
        bis.clearBitCache();
    }
}
